function parse_aggr(aggr_result) {
  var features = [];
  for (var i = 0; i < aggr_result.buckets.length; i++) {
    var bucket = aggr_result.buckets[i];
    var feature = {
      type: 'Feature',
      geometry: {
        type: 'Point',
        coordinates: [bucket.key, bucket.doc_count]
      },
      properties: {
        count: bucket.doc_count
      }
    };
    features.push(feature);
  }
  return {
    type: 'FeatureCollection',
    features: features
  };
}
```

